package com.shopsphere;import static org.junit.jupiter.api.Assertions.*;import jakarta.validation.Validation;import org.junit.jupiter.api.*;import org.springframework.security.crypto.bcrypt.BCryptPasswordEncoder;import org.springframework.security.oauth2.jwt.Jwt;
class AuthServiceTest {UserRepository.InMemory repo;JwtService jwt;AuthService service;@BeforeEach void setup(){repo=new UserRepository.InMemory();jwt=new JwtService("test-secret-that-is-definitely-long-enough",15,7);service=new AuthService(repo,new BCryptPasswordEncoder(4),jwt);}@Test void registrationHashesPasswordAndRejectsDuplicates(){var request=new AuthDtos.RegisterRequest("Aarav","Mehta","AARAV@example.com","Secret123","+91 9876543210");var created=service.register(request);assertEquals("aarav@example.com",created.email());assertTrue(repo.findByEmail(created.email()).orElseThrow().passwordHash().startsWith("$2"));assertThrows(ConflictException.class,()->service.register(request));}@Test void loginAndJwtValidation(){service.register(new AuthDtos.RegisterRequest("A","M","a@example.com","Secret123",null));var tokens=service.login(new AuthDtos.LoginRequest("a@example.com","Secret123"));Jwt parsed=jwt.validate(tokens.accessToken(),"access");assertEquals("a@example.com",parsed.getClaimAsString("email"));assertThrows(UnauthorizedException.class,()->service.login(new AuthDtos.LoginRequest("a@example.com","wrong")));}@Test void viewsAndUpdatesOnlyTheRequestedProfile(){var created=service.register(new AuthDtos.RegisterRequest("Aarav","Mehta","a@example.com","Secret123","+91 9876543210"));var updated=service.updateProfile(created.id(),new AuthDtos.UpdateProfileRequest("Aarav","Sharma","new@example.com","+91 9000000000"));assertEquals("Sharma",updated.lastName());assertEquals("new@example.com",service.me(created.id()).email());assertThrows(NotFoundException.class,()->service.me(java.util.UUID.randomUUID()));}@Test void profileEmailRemainsUnique(){var one=service.register(new AuthDtos.RegisterRequest("One","User","one@example.com","Secret123",null));service.register(new AuthDtos.RegisterRequest("Two","User","two@example.com","Secret123",null));assertThrows(ConflictException.class,()->service.updateProfile(one.id(),new AuthDtos.UpdateProfileRequest("One","User","two@example.com",null)));}@Test void invalidProfileFieldsFailBeanValidation(){try(var factory=Validation.buildDefaultValidatorFactory()){var validator=factory.getValidator();assertFalse(validator.validate(new AuthDtos.UpdateProfileRequest("1","User","invalid","12")).isEmpty());}}@Test void changesPasswordOnlyWhenCurrentPasswordMatches(){var created=service.register(new AuthDtos.RegisterRequest("A","M","a@example.com","Secret123",null));assertThrows(UnauthorizedException.class,()->service.changePassword(created.id(),new AuthDtos.ChangePasswordRequest("wrong","NewSecret123")));service.changePassword(created.id(),new AuthDtos.ChangePasswordRequest("Secret123","NewSecret123"));assertNotNull(service.login(new AuthDtos.LoginRequest("a@example.com","NewSecret123")).accessToken());}}
